content.process:
catalog = get_plugin('DatasetCatalog')
agent_id = (state.get('agent_id') or state.get('runner_id') or 'wf_cid_re_llm_linear').strip()
fmt = (state.get('format') or 're').strip()
source = (state.get('source') or 'data/raw/dev.txt').strip()
try:
    size = int(state.get('size') or 20)
except Exception:
    size = 20
tuning_out = (state.get('tuning_out') or '').strip() or None
test_out = (state.get('test_out') or '').strip() or None
wtr = state.get('write_test_remain', True)
if isinstance(wtr, str):
    write_test_remain = wtr.strip().lower() not in ('0', 'false', 'no', '')
else:
    write_test_remain = bool(wtr if wtr is not None else True)
mirror_agent = (state.get('mirror_agent_id') or '').strip()
mirror_fmt = (state.get('mirror_format') or 'ner').strip()
mirror = [{'agent_id': mirror_agent, 'format': mirror_fmt}] if mirror_agent else None
if not catalog:
    __result__ = {'error': 'DatasetCatalog plugin unavailable'}
else:
    try:
        __result__ = catalog.build_tuning(
            agent_id,
            source=source,
            format=fmt,
            size=size,
            tuning_out=tuning_out,
            test_out=test_out,
            write_test_remain=write_test_remain,
            mirror=mirror,
        )
    except Exception as e:
        __result__ = {'error': str(e), 'agent_id': agent_id, 'source': source, 'size': size}
